/* @lc app=leetcode id=1697 lang=kotlin */
class Solution { fun distanceLimitedPathsExist(n: Int, edgeList: Array<IntArray>, queries: Array<IntArray>): BooleanArray = IntArray(n) { it }.let { parent -> { u: Int -> intArrayOf(u).also { p -> while (parent[p[0]] != p[0]) parent[p[0]] = parent[parent[p[0]]].also { p[0] = it } }[0] }.let { find -> edgeList.sortedBy { it[2] }.let { sortedEdges -> queries.indices.map { i -> intArrayOf(queries[i][0], queries[i][1], queries[i][2], i) }.sortedBy { it[2] }.let { sortedQueries -> BooleanArray(queries.size).also { res -> intArrayOf(0).let { e -> sortedQueries.forEach { q -> q.also { while (e[0] < sortedEdges.size && sortedEdges[e[0]][2] < q[2]) sortedEdges[e[0]].also { edge -> parent[find(edge[0])] = find(edge[1]) }.also { e[0] = e[0] + 1 } }.also { res[q[3]] = find(q[0]) == find(q[1]) } } } } } } } }